import { FormEvent, lazy, Suspense, useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import { Link, NavLink, Outlet, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Activity, AlertOctagon, AlertTriangle, ArrowDownToLine, ArrowRight, ArrowUpRight, Check, ChevronDown, CircleHelp, Clock3, FileBox, FileText, FolderKanban, Gauge, KeyRound, LayoutDashboard, ListFilter, LockKeyhole, LogOut, Menu, Moon, Plus, Search, Settings, Shield, ShieldAlert, ShieldCheck, Sun, Users, X } from 'lucide-react'
import { api } from './api/client'
import { SecurityCenterPage } from './features/SecurityCenter'
import { scanHasStableEvidence } from './scanReadiness'
import type { Component, Finding, Project, User } from './types'
import { safeExternalUrl } from './safeExternalUrl'
import { formatBytes } from './formatBytes'

const SeverityChart = lazy(() => import('./components/SeverityChart'))

function useAuth() { return useQuery({ queryKey: ['me'], queryFn: api.me, retry: false }) }
function date(value?: string | null) { return value ? new Date(value).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) : 'N/A' }

function Brand({ compact = false }: { compact?: boolean }) {
  return <Link className={`brand ${compact ? 'brand-compact' : ''}`} to="/" aria-label="DepShield home"><span className="brand-mark"><ShieldCheck size={20} /></span><span>DepShield</span></Link>
}

function ThemeControl() {
  const [theme, setTheme] = useState(() => localStorage.getItem('depshield-theme') || 'light')
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('depshield-theme', theme) }, [theme])
  return <button className="icon-button" aria-label={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`} onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}>{theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}</button>
}

function App() {
  return <Routes>
    <Route path="/" element={<Landing />} />
    <Route path="/login" element={<AuthPage mode="login" />} />
    <Route path="/register" element={<AuthPage mode="register" />} />
    <Route path="/forgot-password" element={<ForgotPassword />} />
    <Route path="/reset-password" element={<ResetPassword />} />
    <Route path="/about" element={<PublicPage title="About DepShield">DepShield is a locally operated defensive tool for understanding the software components declared in project manifests and checking exact package versions against public vulnerability intelligence.</PublicPage>} />
    <Route path="/how-it-works" element={<PublicPage title="How it works"><ol className="steps-list"><li>Upload a supported dependency manifest or ZIP archive.</li><li>DepShield reads the manifest without installing packages or running project code.</li><li>Resolved versions are queried against OSV and enriched with available CISA KEV and NVD data.</li><li>Review the resulting inventory, evidence, risk heuristic and remediation options.</li></ol></PublicPage>} />
    <Route path="/faq" element={<FAQ />} />
    <Route path="/privacy" element={<PublicPage title="Privacy policy" eyebrow="Draft for local project use">The application stores account details, project metadata, dependency inventories and scan findings in its configured PostgreSQL database. Uploaded bytes are parsed in memory and are not retained. Exact package names, ecosystems and versions are sent to OSV; CVE identifiers may be sent to NVD; CISA KEV is downloaded as a public catalog. If enabled, advisory data only is sent to the locally configured Ollama service. Configure SMTP before requesting password reset. Terminal scan snapshots and their inventory are removed daily after the configured retention period. Project, account and audit records follow separate policies, and backups may retain deleted data until their configured expiry. This implementation-based draft needs operator and legal review before public deployment.</PublicPage>} />
    <Route path="/terms" element={<PublicPage title="Terms and conditions" eyebrow="Draft for local project use">Use DepShield only for defensive analysis of software you are authorized to assess. You are responsible for uploaded data and any actions taken from scan results. Vulnerability matching is package-level and can be incomplete. AI explanations are advisory and should be reviewed. Public intelligence services may be unavailable or rate limited. The project does not provide a security certification or guarantee that software is free of vulnerabilities. The operator may suspend accounts used abusively. Review with an appropriate legal adviser before public deployment.</PublicPage>} />
    <Route path="/cookies" element={<PublicPage title="Cookie information">DepShield uses an essential session cookie and a CSRF cookie to authenticate and protect state-changing requests. The application does not include optional analytics or advertising cookies. Theme preference is stored in this browser. No optional tracking consent is requested because no optional tracking is enabled.</PublicPage>} />
    <Route path="/free-use" element={<PublicPage title="Free use and refunds">DepShield does not collect payments and has no paid subscription or refund process.</PublicPage>} />
    <Route path="/app" element={<ProtectedLayout />}>
      <Route index element={<Dashboard />} />
      <Route path="projects" element={<ProjectsPage />} />
      <Route path="projects/:projectId" element={<ProjectPage />} />
      <Route path="scans/:scanId" element={<ScanPage />} />
      <Route path="vulnerabilities" element={<ExplorerPage />} />
      <Route path="security" element={<SecurityCenterPage />} />
      <Route path="settings" element={<SettingsPage />} />
      <Route path="admin" element={<AdminPage />} />
    </Route>
    <Route path="*" element={<NotFound />} />
  </Routes>
}

function Landing() {
  const { data, isLoading } = useAuth()
  return <div className="public-shell"><header className="public-header"><Brand /><nav aria-label="Main navigation" className="public-nav"><Link to="/about">About</Link><Link to="/how-it-works">How it works</Link><Link to="/faq">FAQ</Link></nav><div className="header-actions"><ThemeControl />{!isLoading && data?.user ? <Link className="button button-primary button-small" to="/app">Open dashboard <ArrowRight size={15} /></Link> : <><Link className="button button-quiet button-small" to="/login">Sign in</Link><Link className="button button-primary button-small" to="/register">Create account</Link></>}</div></header>
    <main>
      <section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="status-dot" /> SOFTWARE SUPPLY CHAIN SECURITY</div><h1>Identify vulnerable dependencies before they become security incidents.</h1><p>Analyze project manifests, generate a CycloneDX SBOM, prioritize known vulnerabilities and review remediation evidence using public security intelligence.</p><div className="hero-actions"><Link className="button button-primary" to={data?.user ? '/app/projects' : '/register'}>Start a security scan <ArrowRight size={17} /></Link><Link className="button button-outline" to="/how-it-works">See how it works</Link></div><div className="hero-proof"><span><Check size={15} /> No package installation</span><span><Check size={15} /> Local AI is optional</span><span><Check size={15} /> Public intelligence sources</span></div></div>
      <div className="hero-visual" aria-label="DepShield scan workflow diagram"><div className="visual-top"><span className="visual-label"><Shield size={14} /> Scan workflow</span><span className="pill pill-neutral">Local analysis</span></div><div className="workflow-visual"><div className="workflow-step"><span className="workflow-icon"><FileText size={18} /></span><div><strong>Dependency manifest</strong><small>Read-only parsing</small></div><Check size={16} className="workflow-check" /></div><div className="workflow-connector" /><div className="workflow-step"><span className="workflow-icon accent"><Search size={18} /></span><div><strong>Public intelligence</strong><small>OSV · NVD · CISA KEV</small></div><ArrowRight size={16} className="workflow-arrow" /></div><div className="workflow-connector" /><div className="workflow-step"><span className="workflow-icon cream"><FileBox size={18} /></span><div><strong>Reviewable results</strong><small>SBOM · risk factors · reports</small></div><Check size={16} className="workflow-check" /></div></div><div className="visual-foot"><LockKeyhole size={14} /> Uploaded project code is never executed.</div></div></section>
      <section className="trust-strip"><div><strong>5</strong><span>manifest ecosystems</span></div><div><strong>OSV</strong><span>version-based matching</span></div><div><strong>SBOM</strong><span>CycloneDX JSON</span></div><div><strong>Local</strong><span>Ollama explanations</span></div></section>
      <section className="public-section"><div className="section-heading"><span className="eyebrow">BUILT FOR DEFENSIVE WORKFLOWS</span><h2>From dependency list to actionable evidence</h2><p>DepShield keeps package inventory, public advisory data and prioritization evidence together in one local project workspace.</p></div><div className="feature-grid"><Feature icon={<FileBox />} title="Dependency inventory" text="Parse common lockfiles and manifests without installing packages, building the application or executing uploaded code." /><Feature icon={<ShieldAlert />} title="Vulnerability context" text="Match exact resolved versions with OSV and add CISA KEV and NVD context when those sources are available." /><Feature icon={<Activity />} title="Transparent priority" text="See the factors behind the DepShield heuristic while keeping official severity distinct from local prioritization." /></div></section>
      <section className="bottom-cta"><div><span className="eyebrow">OPEN SOURCE TOOLING · LOCAL DATABASE</span><h2>Start with a manifest you already have.</h2><p>Use the hosted application locally with PostgreSQL. No paid API is required.</p></div><Link to={data?.user ? '/app/projects' : '/register'} className="button button-primary">Create a project <ArrowRight size={17} /></Link></section>
    </main><PublicFooter /></div>
}

function Feature({ icon, title, text }: { icon: ReactNode; title: string; text: string }) { return <article className="feature-card"><span className="feature-icon">{icon}</span><h3>{title}</h3><p>{text}</p></article> }

function PublicFooter() { return <footer className="public-footer"><Brand compact /><span>© {new Date().getFullYear()} DepShield · Local project</span><nav aria-label="Policy links"><Link to="/privacy">Privacy</Link><Link to="/terms">Terms</Link><Link to="/cookies">Cookies</Link><Link to="/free-use">Free use</Link></nav></footer> }

function PublicPage({ title, children, eyebrow = 'DEPSHIELD INFORMATION' }: { title: string; children: ReactNode; eyebrow?: string }) { useEffect(() => { document.title = `${title} | DepShield` }, [title]); return <div className="public-shell"><header className="public-header"><Brand /><nav className="public-nav"><Link to="/about">About</Link><Link to="/faq">FAQ</Link></nav><div className="header-actions"><ThemeControl /><Link to="/login" className="button button-quiet button-small">Sign in</Link></div></header><main className="prose-page"><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><div className="prose-content">{children}</div><p className="updated-note">Last updated: November 26, 2026</p><Link className="button button-outline" to="/">Back to home</Link></main><PublicFooter /></div> }

function FAQ() { const questions = [['Does DepShield install packages?', 'No. It parses supported dependency files and never runs package installation, build scripts or uploaded source code.'], ['Does a clean scan prove a project is secure?', 'No. Results depend on resolved versions and available intelligence. Unpinned or unresolved dependencies are reported as unverified, and package-level matches do not establish reachability.'], ['Is AI required?', 'No. Deterministic risk scoring, SBOM generation, reports and vulnerability matching do not require Ollama. Fallback explanations are labelled deterministic.'], ['What is retained?', 'Manifest bytes are parsed in memory and discarded. Terminal scan snapshots are removed daily after the configured retention period. Project and account records remain until deletion; audit events are not automatically pruned. Backups may retain deleted data until their configured expiry.'], ['What does a partial scan mean?', 'One or more required sources or dependency resolutions were unavailable. A partial result must not be interpreted as having no vulnerability findings.']]; return <PublicPage title="Frequently asked questions"><div className="faq-list">{questions.map(([q, a]) => <details key={q}><summary>{q}<ChevronDown size={18} /></summary><p>{a}</p></details>)}</div></PublicPage> }

function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const navigate = useNavigate(); const qc = useQueryClient(); const register = mode === 'register';
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [displayName, setDisplayName] = useState(''); const [show, setShow] = useState(false); const [accepted, setAccepted] = useState(false); const [age, setAge] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('');
  const mutation = useMutation<{ user: User } | { message: string }, Error, void>({ mutationFn: async () => register ? await api.register(displayName, email, password) : await api.login(email, password), onSuccess: async (result) => { if ('message' in result) setMessage(result.message); else { await qc.invalidateQueries({ queryKey: ['me'] }); navigate('/app') } }, onError: (e) => setError(e instanceof Error ? e.message : 'Request failed') });
  function submit(event: FormEvent) { event.preventDefault(); setError(''); setMessage(''); if (register && (!accepted || !age)) { setError('Confirm the Privacy and Terms acknowledgement and age requirement.'); return } mutation.mutate() }
  return <div className="auth-layout"><aside className="auth-aside"><Brand /><div className="auth-aside-copy"><span className="eyebrow">DEPENDENCY RISK, IN CONTEXT</span><h1>Build with a clearer view of your software supply chain.</h1><p>Scan manifests, preserve a component inventory and understand which results need your attention.</p><div className="auth-mini-card"><ShieldCheck size={19} /><div><strong>Evidence stays visible</strong><span>Source status accompanies every scan.</span></div></div></div><span className="auth-aside-foot">Defensive analysis · Local-first configuration</span></aside><main className="auth-main"><div className="auth-mobile-brand"><Brand /></div><div className="auth-card"><Link className="back-link" to="/">← Back to home</Link><div className="auth-heading"><span className="eyebrow">{register ? 'CREATE YOUR WORKSPACE' : 'WELCOME BACK'}</span><h2>{register ? 'Create your account' : 'Sign in to DepShield'}</h2><p>{register ? 'Your account starts with the Developer role.' : 'Continue to your project security workspace.'}</p></div>
    <form onSubmit={submit} className="form-stack">{register && <label>Display name<input autoComplete="name" value={displayName} onChange={e => setDisplayName(e.target.value)} required maxLength={100} /></label>}<label>Email address<input type="email" autoComplete="email" value={email} onChange={e => setEmail(e.target.value)} required maxLength={320} /></label><label>Password<span className="password-wrap"><input type={show ? 'text' : 'password'} autoComplete={register ? 'new-password' : 'current-password'} value={password} onChange={e => setPassword(e.target.value)} required minLength={register ? 12 : 1} maxLength={128} /><button type="button" onClick={() => setShow(!show)} aria-label={show ? 'Hide password' : 'Show password'}>{show ? 'Hide' : 'Show'}</button></span>{register && <small>Use at least 12 characters.</small>}</label>
    {register && <div className="consent-stack"><label className="check-label"><input type="checkbox" checked={accepted} onChange={e => setAccepted(e.target.checked)} /> <span>I agree to the <Link to="/terms">Terms</Link> and acknowledge the <Link to="/privacy">Privacy Policy</Link>.</span></label><label className="check-label"><input type="checkbox" checked={age} onChange={e => setAge(e.target.checked)} /> <span>I confirm I am at least 18 years old.</span></label></div>}
    {error && <p className="form-alert error" role="alert">{error}</p>}{message && <p className="form-alert success" role="status">{message} <Link to="/login">Sign in</Link></p>}<button className="button button-primary button-full" disabled={mutation.isPending}>{mutation.isPending ? 'Please wait…' : register ? 'Create account' : 'Sign in'} <ArrowRight size={16} /></button>
    </form>{!register && <Link className="forgot-link" to="/forgot-password">Forgot password?</Link>}<div className="auth-switch">{register ? 'Already have an account?' : 'New to DepShield?'} <Link to={register ? '/login' : '/register'}>{register ? 'Sign in' : 'Create account'}</Link></div><p className="auth-privacy">Essential session and CSRF cookies protect your account. No analytics cookies are enabled.</p></div><PublicFooter /></main></div>
}

function ForgotPassword() { const [email, setEmail] = useState(''); const [done, setDone] = useState(false); const [error, setError] = useState(''); const m = useMutation({ mutationFn: () => api.resetRequest(email), onSuccess: () => setDone(true), onError: e => setError(e.message) }); return <div className="auth-layout"><aside className="auth-aside"><Brand /><div className="auth-aside-copy"><span className="eyebrow">ACCOUNT RECOVERY</span><h1>Reset access securely.</h1><p>Reset links are single-use and expire. Configure the local email service to receive a message.</p></div></aside><main className="auth-main"><div className="auth-card"><Link to="/login" className="back-link">← Back to sign in</Link><span className="auth-icon"><KeyRound size={21} /></span><h2>Forgot password?</h2><p>Enter your account email. If an active account matches, reset instructions will be sent.</p>{done ? <p role="status" className="form-alert success">If an active account matches that address, password reset instructions will be sent.</p> : <form className="form-stack" onSubmit={e => { e.preventDefault(); m.mutate() }}><label>Email address<input type="email" required value={email} onChange={e => setEmail(e.target.value)} /></label>{error && <p className="form-alert error" role="alert">{error}</p>}<button className="button button-primary button-full" disabled={m.isPending}>Send reset instructions</button></form>}</div><PublicFooter /></main></div> }

function ResetPassword() { const token = new URLSearchParams(location.search).get('token') || ''; const [password, setPassword] = useState(''); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const m = useMutation({ mutationFn: () => api.resetComplete(token, password), onSuccess: r => setMessage(r.message), onError: e => setError(e.message) }); return <div className="center-page"><div className="auth-card"><Brand /><h2>Choose a new password</h2><p>Reset links can only be used once and expire after a short time.</p><form className="form-stack" onSubmit={e => { e.preventDefault(); m.mutate() }}><label>New password<input type="password" minLength={12} maxLength={128} required value={password} onChange={e => setPassword(e.target.value)} /></label>{error && <p className="form-alert error" role="alert">{error}</p>}{message && <p className="form-alert success" role="status">{message}</p>}<button className="button button-primary button-full" disabled={m.isPending || !token}>Update password</button></form><Link to="/login" className="back-link">Back to sign in</Link></div></div> }

function ProtectedLayout() {
  const auth = useAuth(); const location = useLocation(); const navigate = useNavigate(); const qc = useQueryClient(); const [mobileOpen, setMobileOpen] = useState(false);
  const logout = useMutation({ mutationFn: api.logout, onSuccess: () => { qc.setQueryData(['me'], null); navigate('/login') } });
  useEffect(() => { if (auth.isError) navigate('/login', { replace: true, state: { from: location.pathname } }) }, [auth.isError, location.pathname, navigate]);
  if (auth.isLoading || !auth.data?.user) return <div className="loading-screen"><div className="spinner" /><span>Loading workspace</span></div>;
  const user = auth.data.user;
  return <div className="app-shell"><a className="skip-link" href="#main-content">Skip to content</a><aside className={`sidebar ${mobileOpen ? 'sidebar-open' : ''}`}><div className="sidebar-head"><Brand /><button className="icon-button mobile-close" onClick={() => setMobileOpen(false)} aria-label="Close menu"><X size={19} /></button></div><div className="workspace-switch"><div className="workspace-avatar">D</div><span><strong>Personal workspace</strong><small>{user.role}</small></span><ChevronDown size={15} /></div><nav className="side-nav" aria-label="Workspace navigation"><span className="nav-label">WORKSPACE</span><NavLink end to="/app" onClick={() => setMobileOpen(false)}><LayoutDashboard size={17} /> Overview</NavLink><NavLink to="/app/projects" onClick={() => setMobileOpen(false)}><FolderKanban size={17} /> Projects</NavLink><NavLink to="/app/vulnerabilities" onClick={() => setMobileOpen(false)}><ShieldAlert size={17} /> Vulnerabilities</NavLink><NavLink to="/app/security" onClick={() => setMobileOpen(false)}><ShieldCheck size={17} /> Security center</NavLink><span className="nav-label nav-label-gap">ACCOUNT</span><NavLink to="/app/settings" onClick={() => setMobileOpen(false)}><Settings size={17} /> Settings</NavLink>{user.role === 'administrator' && <><span className="nav-label nav-label-gap">ADMINISTRATION</span><NavLink to="/app/admin" onClick={() => setMobileOpen(false)}><Users size={17} /> Admin console</NavLink></>}</nav><div className="sidebar-bottom"><div className="source-status"><span className="status-dot status-dot-muted" /><div><strong>Public intelligence</strong><small>Checked per scan</small></div><CircleHelp size={14} /></div><div className="user-menu"><div className="user-avatar">{user.display_name.slice(0, 1).toUpperCase()}</div><div className="user-meta"><strong>{user.display_name}</strong><span>{user.email}</span></div><button className="icon-button logout-button" aria-label="Sign out" title="Sign out" onClick={() => logout.mutate()}><LogOut size={17} /></button></div></div></aside><div className="app-main-wrap"><header className="app-header"><button className="icon-button mobile-menu" aria-label="Open menu" onClick={() => setMobileOpen(true)}><Menu size={19} /></button><div className="breadcrumb"><span>Workspace</span><span className="crumb-slash">/</span><strong>{location.pathname.split('/').filter(Boolean).pop()?.replace(/-/g, ' ') || 'Overview'}</strong></div><div className="header-spacer" /><Link to="/app/vulnerabilities" className="header-search"><Search size={16} /><span>Search vulnerabilities…</span><kbd>/</kbd></Link><ThemeControl /></header><main id="main-content" className="app-content"><Outlet context={{ user }} /></main><footer className="app-footer"><span>DepShield · Defensive analysis workspace</span><span><Link to="/privacy">Privacy</Link><span> · </span><Link to="/terms">Terms</Link><span> · </span>{new Date().getFullYear()}</span></footer></div>{mobileOpen && <button className="mobile-backdrop" aria-label="Close navigation" onClick={() => setMobileOpen(false)} />}</div>
}

function useWorkspaceUser() { return useAuth().data?.user }

function PageTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { useEffect(() => { document.title = `${title} | DepShield` }, [title]); return <div className="page-title-row"><div><div className="eyebrow">{eyebrow || 'WORKSPACE'}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</div> }
function LoadingBlock({ label = 'Loading data…' }: { label?: string }) { return <div className="loading-block"><div className="spinner" /><span>{label}</span></div> }
function ErrorBlock({ error, retry }: { error: unknown; retry?: () => void }) { return <div className="error-block" role="alert"><AlertTriangle size={18} /><span>{error instanceof Error ? error.message : 'Could not load this data.'}</span>{retry && <button className="button button-outline button-small" onClick={retry}>Retry</button>}</div> }
function EmptyState({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon">{icon}</span><h3>{title}</h3><p>{text}</p>{action}</div> }

function Dashboard() {
  const user = useWorkspaceUser()
  const { data, isLoading, error, refetch } = useQuery({ queryKey: ['dashboard'], queryFn: api.dashboard });
  if (isLoading) return <LoadingBlock />; if (error) return <ErrorBlock error={error} retry={() => void refetch()} />;
  const counts = data?.priority_counts || {};
  const chart = ['Critical', 'High', 'Medium', 'Low', 'Unknown'].map(name => ({ name, findings: counts[name] || 0 }));
  const findingsTotal = Object.values(counts).reduce((total, count) => total + count, 0);
  const firstName = user?.display_name.trim().split(/\s+/)[0] || 'there';
  return <div className="dashboard-page">
    <PageTitle eyebrow="SECURITY OVERVIEW" title={`Welcome back, ${firstName}`} description="Your software supply chain, with the latest scan evidence in one place." action={user?.role !== 'auditor' && <Link className="button button-primary" to="/app/projects"><Plus size={17} /> Start a scan</Link>} />
    <div className="metric-grid">
      <Metric icon={<FolderKanban />} label="Projects" value={data?.projects || 0} detail="Projects you can access" tone="slate" />
      <Metric icon={<FileBox />} label="Dependencies" value={data?.components || 0} detail="Across saved scan snapshots" tone="cream" />
      <Metric icon={<ShieldAlert />} label="Vulnerability findings" value={findingsTotal} detail="Stored across scan history" tone="gold" />
      <Metric icon={<AlertOctagon />} label="Critical priority" value={counts.Critical || 0} detail="DepShield risk heuristic" tone="red" />
    </div>
    <div className="dashboard-grid">
      <section className="panel chart-panel"><div className="panel-heading"><div><span className="section-kicker">RISK DISTRIBUTION</span><h2>Findings by priority</h2><p>Priority is DepShield’s heuristic; official severity stays in each finding.</p></div><span className="panel-icon"><Gauge size={17} /></span></div>{data?.scans ? <><Suspense fallback={<div className="chart-wrap" aria-label="Loading chart" />}><SeverityChart data={chart} /></Suspense><p className="chart-summary">{chart.map(item => `${item.name}: ${item.findings}`).join(' · ')}</p></> : <EmptyState icon={<ShieldCheck />} title="No scan data yet" text="Create a project and upload a dependency file to see actual results." action={<Link to="/app/projects" className="button button-outline">View projects</Link>} />}</section>
      <section className="panel activity-panel"><div className="panel-heading"><div><span className="section-kicker">LATEST ACTIVITY</span><h2>Recent scans</h2><p>Latest scans across your accessible projects.</p></div><Link to="/app/projects" className="text-link">All projects <ArrowRight size={14} /></Link></div>{data?.recent_scans.length ? <div className="activity-list">{data.recent_scans.map(scan => <Link to={`/app/scans/${scan.id}`} className="activity-item" key={scan.id}><span className={`activity-status status-${scan.status}`}><ScanIcon status={scan.status} /></span><span className="activity-main"><strong>{scan.source_filename}</strong><small>{date(scan.created_at)}</small></span><StatusBadge status={scan.status} /><ArrowUpRight className="activity-arrow" size={15} /></Link>)}</div> : <EmptyState icon={<Clock3 />} title="Nothing scanned yet" text="Scan history will appear here after the first job finishes." />}</section>
    </div>
    <section className="info-banner"><div className="info-icon"><ShieldCheck size={19} /></div><div><strong>Source availability is part of every result</strong><p>A partial scan means one or more intelligence sources or dependency resolutions were unavailable. It should not be treated as a clean security result.</p></div><Link to="/how-it-works" aria-label="Read how DepShield works"><ArrowRight size={17} /></Link></section>
  </div>
}
function Metric({ icon, label, value, detail, tone }: { icon: ReactNode; label: string; value: number; detail: string; tone: string }) { return <article className="metric-card"><span className={`metric-icon ${tone}`}>{icon}</span><span className="metric-label">{label}</span><strong className="metric-value">{value.toLocaleString()}</strong><span className="metric-detail">{detail}</span></article> }
function MetricText({ icon, label, value, detail, tone }: { icon: ReactNode; label: string; value: string; detail: string; tone: string }) { return <article className="metric-card"><span className={`metric-icon ${tone}`}>{icon}</span><span className="metric-label">{label}</span><strong className="metric-value metric-text-value">{value}</strong><span className="metric-detail">{detail}</span></article> }
function ScanIcon({ status }: { status: string }) { return status === 'completed' ? <Check size={15} /> : status === 'failed' ? <X size={15} /> : <Clock3 size={15} /> }
function StatusBadge({ status }: { status: string }) { const label = status.replace('_', ' '); return <span className={`status-badge status-${status}`}><span className="status-bullet" />{label}</span> }

function ProjectsPage() {
  const user = useWorkspaceUser(); const query = useQuery({ queryKey: ['projects'], queryFn: api.projects }); const [open, setOpen] = useState(false); const nav = useNavigate(); const canCreate = user?.role !== 'auditor'; const qc = useQueryClient();
  const [name, setName] = useState(''); const [description, setDescription] = useState(''); const [ecosystem, setEcosystem] = useState('mixed'); const [error, setError] = useState('');
  const create = useMutation({ mutationFn: () => api.createProject({ name, description, ecosystem }), onSuccess: async p => { await qc.invalidateQueries({ queryKey: ['projects'] }); setOpen(false); setName(''); nav(`/app/projects/${p.id}`) }, onError: e => setError(e.message) });
  const del = useMutation({ mutationFn: api.deleteProject, onSuccess: () => qc.invalidateQueries({ queryKey: ['projects'] }) });
  const projects = query.data?.items || [];
  return <><PageTitle eyebrow="PROJECT INVENTORY" title="Projects" description="Group dependency manifests and keep scan history with the codebase they belong to." action={canCreate && <button className="button button-primary" onClick={() => setOpen(true)}><Plus size={17} /> Create project</button>} />
    {query.isLoading ? <LoadingBlock /> : query.error ? <ErrorBlock error={query.error} retry={() => void query.refetch()} /> : !projects.length ? <section className="panel"><EmptyState icon={<FolderKanban />} title="No projects yet" text={user?.role === 'auditor' ? 'No projects have been shared with this account.' : 'Create a project to organize manifests and scan history.'} action={canCreate && <button className="button button-primary" onClick={() => setOpen(true)}><Plus size={16} /> Create your first project</button>} /></section> : <div className="project-grid">{projects.map(project => <ProjectCard key={project.id} project={project} onOpen={() => nav(`/app/projects/${project.id}`)} onDelete={() => { if (confirm(`Delete “${project.name}” and all associated scans? This cannot be undone.`)) del.mutate(project) }} canDelete={user?.role === 'administrator' || project.owner_id === user?.id} />)}</div>}
    {open && <div className="modal-backdrop" role="presentation" onMouseDown={e => { if (e.target === e.currentTarget) setOpen(false) }}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="create-project-title"><div className="modal-header"><div><span className="eyebrow">PROJECT SETUP</span><h2 id="create-project-title">Create a project</h2></div><button className="icon-button" onClick={() => setOpen(false)} aria-label="Close dialog"><X size={19} /></button></div><form className="form-stack" onSubmit={e => { e.preventDefault(); setError(''); create.mutate() }}><label>Project name<input autoFocus required maxLength={120} value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Payments API" /></label><label>Description <span className="optional-label">Optional</span><textarea rows={3} maxLength={1000} value={description} onChange={e => setDescription(e.target.value)} placeholder="Purpose or owner notes" /></label><label>Primary ecosystem<select value={ecosystem} onChange={e => setEcosystem(e.target.value)}><option value="mixed">Mixed / not set</option><option value="python">Python</option><option value="javascript">JavaScript</option><option value="java">Java</option><option value="go">Go</option><option value="rust">Rust</option></select></label>{error && <p className="form-alert error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button button-outline" onClick={() => setOpen(false)}>Cancel</button><button className="button button-primary" disabled={create.isPending}>{create.isPending ? 'Creating…' : 'Create project'}</button></div></form></section></div>}
  </>
}

function ProjectCard({ project, onOpen, onDelete, canDelete }: { project: Project; onOpen: () => void; onDelete: () => void; canDelete: boolean }) { const count = useQuery({ queryKey: ['project-scans', project.id], queryFn: () => api.scans(project.id), staleTime: 30_000 }); const latest = project.latest_scan; return <article className="project-card"><button className="project-card-open" onClick={onOpen} aria-label={`Open ${project.name}`}><span className="project-symbol"><FolderKanban size={19} /></span><span className="project-title"><strong>{project.name}</strong><small>{project.ecosystem}</small></span><ArrowUpRight size={17} /></button><p className="project-description">{project.description || 'No description provided.'}</p><div className="project-card-stats"><span><FileText size={14} /> {count.data?.items.length ?? 'N/A'} scans</span><span><Clock3 size={14} /> {latest ? date(latest.created_at) : 'Never scanned'}</span></div><div className="project-card-bottom"><StatusBadge status={project.archived ? 'archived' : latest?.status || 'not_scanned'} />{canDelete && <button className="text-button danger-text" onClick={onDelete}>Delete</button>}</div></article> }

function ProjectPage() {
  const { projectId = '' } = useParams()
  const user = useWorkspaceUser()
  const qc = useQueryClient()
  const projectQuery = useQuery({ queryKey: ['projects'], queryFn: api.projects })
  const scansQuery = useQuery({ queryKey: ['project-scans', projectId], queryFn: () => api.scans(projectId), refetchInterval: q => q.state.data?.items.some(s => ['queued', 'processing'].includes(s.status)) ? 2500 : false })
  const project = projectQuery.data?.items.find(p => p.id === projectId)
  const [uploadError, setUploadError] = useState('')
  const [dragging, setDragging] = useState(false)
  const [projectOpen, setProjectOpen] = useState(false)
  const [projectDraft, setProjectDraft] = useState({ name: '', description: '', ecosystem: 'mixed' })
  const [manageError, setManageError] = useState('')
  const upload = useMutation({ mutationFn: (file: File) => api.upload(projectId, file), onSuccess: async () => { await qc.invalidateQueries({ queryKey: ['project-scans', projectId] }); await qc.invalidateQueries({ queryKey: ['projects'] }); setUploadError('') }, onError: e => setUploadError(e.message) })
  const update = useMutation({ mutationFn: (input: { name: string; description: string; ecosystem: string }) => api.updateProject(projectId, input), onSuccess: async () => { await qc.invalidateQueries({ queryKey: ['projects'] }); setProjectOpen(false); setManageError('') }, onError: e => setManageError(e.message) })
  const archive = useMutation({ mutationFn: (archived: boolean) => api.updateProject(projectId, { archived }), onSuccess: () => qc.invalidateQueries({ queryKey: ['projects'] }), onError: e => setManageError(e.message) })
  if (projectQuery.isLoading) return <LoadingBlock />
  if (projectQuery.error) return <ErrorBlock error={projectQuery.error} />
  if (!project) return <NotFound />
  const selectedProject = project
  const canManage = user?.role === 'administrator' || selectedProject.owner_id === user?.id
  const canScan = canManage && !selectedProject.archived
  function choose(file?: File) {
    if (!file) return
    if (file.size > 10 * 1024 * 1024) { setUploadError('Files must be 10 MB or smaller.'); return }
    upload.mutate(file)
  }
  function editProject() {
    setProjectDraft({ name: selectedProject.name, description: selectedProject.description, ecosystem: selectedProject.ecosystem })
    setManageError('')
    setProjectOpen(true)
  }
  function toggleArchive() {
    const action = selectedProject.archived ? 'restore' : 'archive'
    if (confirm(`Are you sure you want to ${action} “${selectedProject.name}”?`)) archive.mutate(!selectedProject.archived)
  }
  return <>
    <div className="back-crumb"><Link to="/app/projects">Projects</Link><span>/</span>{selectedProject.name}</div>
    <PageTitle eyebrow={`${selectedProject.ecosystem.toUpperCase()} PROJECT`} title={selectedProject.name} description={selectedProject.description || 'Track manifests, components and vulnerability scan history for this selectedProject.'} action={<div className="project-actions">{canManage && <><button className="button button-outline button-small" onClick={editProject}>Edit project</button><button className="button button-outline button-small" onClick={toggleArchive} disabled={archive.isPending}>{selectedProject.archived ? 'Restore project' : 'Archive project'}</button></>}{canScan && <label className="button button-primary upload-top-button"><Plus size={16} /> Upload manifest<input type="file" hidden accept="requirements.txt,package-lock.json,pom.xml,go.mod,Cargo.lock,.zip,application/zip" onChange={e => choose(e.target.files?.[0])} /></label>}</div>} />
    {selectedProject.archived && <div className="scan-status-banner partial" role="status"><span className="scan-status-symbol"><FolderKanban size={18} /></span><div><strong>Project archived</strong><p>New scans are disabled until this project is restored.</p></div><StatusBadge status="archived" /></div>}
    {canScan && <section className={`upload-zone ${dragging ? 'dragging' : ''}`} onDragOver={e => { e.preventDefault(); setDragging(true) }} onDragLeave={() => setDragging(false)} onDrop={e => { e.preventDefault(); setDragging(false); choose(e.dataTransfer.files[0]) }}><span className="upload-icon"><ArrowDownToLine size={20} /></span><div><strong>Drop a manifest or ZIP archive here</strong><p>Supported: requirements.txt, package-lock.json, pom.xml, go.mod, Cargo.lock, ZIP · Maximum 10 MB</p></div><label className="button button-outline button-small">Choose file<input hidden type="file" accept="requirements.txt,package-lock.json,pom.xml,go.mod,Cargo.lock,.zip,application/zip" onChange={e => choose(e.target.files?.[0])} /></label>{upload.isPending && <span className="upload-progress" role="status"><span className="spinner spinner-small" /> Parsing and queueing scan…</span>}{uploadError && <span className="upload-error" role="alert">{uploadError}</span>}</section>}
    {manageError && !projectOpen && <p className="form-alert error" role="alert">{manageError}</p>}
    {projectOpen && <div className="modal-backdrop" role="presentation" onMouseDown={e => { if (e.target === e.currentTarget) setProjectOpen(false) }}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="edit-project-title"><div className="modal-header"><div><span className="eyebrow">PROJECT SETTINGS</span><h2 id="edit-project-title">Edit project</h2></div><button className="icon-button" onClick={() => setProjectOpen(false)} aria-label="Close dialog"><X size={19} /></button></div><form className="form-stack" onSubmit={e => { e.preventDefault(); setManageError(''); update.mutate(projectDraft) }}><label>Project name<input autoFocus required maxLength={120} value={projectDraft.name} onChange={e => setProjectDraft({ ...projectDraft, name: e.target.value })} /></label><label>Description <span className="optional-label">Optional</span><textarea rows={3} maxLength={1000} value={projectDraft.description} onChange={e => setProjectDraft({ ...projectDraft, description: e.target.value })} /></label><label>Primary ecosystem<select value={projectDraft.ecosystem} onChange={e => setProjectDraft({ ...projectDraft, ecosystem: e.target.value })}><option value="mixed">Mixed / not set</option><option value="python">Python</option><option value="javascript">JavaScript</option><option value="java">Java</option><option value="go">Go</option><option value="rust">Rust</option></select></label>{manageError && <p className="form-alert error" role="alert">{manageError}</p>}<div className="modal-actions"><button type="button" className="button button-outline" onClick={() => setProjectOpen(false)}>Cancel</button><button className="button button-primary" disabled={update.isPending}>{update.isPending ? 'Saving…' : 'Save changes'}</button></div></form></section></div>}
    <section className="section-block"><div className="section-heading-inline"><div><h2>Scan history</h2><p>Each scan preserves the dependency and source-availability snapshot.</p></div><span className="count-chip">{scansQuery.data?.items.length ?? 0} scans</span></div>{scansQuery.isLoading ? <LoadingBlock /> : scansQuery.error ? <ErrorBlock error={scansQuery.error} retry={() => void scansQuery.refetch()} /> : !scansQuery.data?.items.length ? <div className="panel"><EmptyState icon={<FileBox />} title="No scans yet" text={canScan ? 'Upload a supported dependency manifest to begin the first scan.' : 'No scans have been recorded for this selectedProject.'} /></div> : <div className="table-panel"><div className="table-scroll"><table><thead><tr><th>Source file</th><th>Status</th><th>Source coverage</th><th>Started</th><th>Duration</th><th /></tr></thead><tbody>{scansQuery.data.items.map(scan => <tr key={scan.id}><td><Link className="table-link" to={`/app/scans/${scan.id}`}><FileText size={15} />{scan.source_filename}</Link></td><td><StatusBadge status={scan.status} />{scan.status === 'processing' && <span className="stage-label">{scan.stage}</span>}</td><td><SourceSummary status={scan.intelligence_status} /></td><td>{date(scan.created_at)}</td><td>{scan.completed_at ? duration(scan.started_at, scan.completed_at) : 'N/A'}</td><td><Link to={`/app/scans/${scan.id}`} className="icon-button" aria-label="Open scan"><ArrowRight size={16} /></Link></td></tr>)}</tbody></table></div></div>}</section>
    <AuditorAccess projectId={selectedProject.id} canManage={canManage} />
  </>
}function duration(start?: string | null, end?: string | null) { if (!start || !end) return 'N/A'; const sec = Math.round((new Date(end).getTime() - new Date(start).getTime()) / 1000); return sec < 60 ? `${sec}s` : `${Math.floor(sec / 60)}m ${sec % 60}s` }
function SourceSummary({ status }: { status: Record<string, string> }) { if (!status || !Object.keys(status).length) return <span className="muted">Pending</span>; return <span className={`source-summary ${['available', 'cached'].includes(status.osv) && ['available', 'cached'].includes(status.cisa_kev) ? 'source-good' : 'source-partial'}`}>{status.osv || 'OSV pending'} · KEV {status.cisa_kev || 'pending'}</span> }

function AuditorAccess({ projectId, canManage }: { projectId: string; canManage: boolean }) { const qc = useQueryClient(); const members = useQuery({ queryKey: ['members', projectId], queryFn: () => api.members(projectId), enabled: canManage }); const [email, setEmail] = useState(''); const [error, setError] = useState(''); const add = useMutation({ mutationFn: () => api.addMember(projectId, email), onSuccess: async () => { setEmail(''); await qc.invalidateQueries({ queryKey: ['members', projectId] }) }, onError: e => setError(e.message) }); const remove = useMutation({ mutationFn: (id: string) => api.removeMember(projectId, id), onSuccess: () => qc.invalidateQueries({ queryKey: ['members', projectId] }) }); if (!canManage) return null; return <section className="section-block"><div className="section-heading-inline"><div><h2>Read-only project access</h2><p>Share this project with an existing account as an Auditor.</p></div></div><div className="panel member-panel"><form className="member-form" onSubmit={e => { e.preventDefault(); setError(''); add.mutate() }}><label className="sr-only" htmlFor="auditor-email">Auditor email address</label><input id="auditor-email" type="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="name@example.com" /><button className="button button-outline button-small" disabled={add.isPending}><Plus size={15} /> Grant read-only access</button></form>{error && <p className="form-alert error" role="alert">{error}</p>}{members.isLoading ? <LoadingBlock label="Loading project access…" /> : members.error ? <ErrorBlock error={members.error} /> : members.data?.items.length ? <div className="member-list">{members.data.items.map(member => <div className="member-row" key={member.id}><span className="user-avatar">{member.display_name.slice(0, 1).toUpperCase()}</span><span><strong>{member.display_name}</strong><small>{member.email}</small></span><StatusBadge status="auditor" /><button className="button button-quiet button-small" onClick={() => remove.mutate(member.user_id)} disabled={remove.isPending}>Revoke</button></div>)}</div> : <p className="member-empty">No auditor access has been granted.</p>}</div></section> }

function ScanPage() {
  const { scanId = '' } = useParams(); const [tab, setTab] = useState<'findings' | 'components'>('findings'); const [q, setQ] = useState('');
  const scanQuery = useQuery({ queryKey: ['scan', scanId], queryFn: () => api.scan(scanId), refetchInterval: query => query.state.data && ['queued', 'processing'].includes(query.state.data.status) ? 2000 : false });
  const scanReady = scanHasStableEvidence(scanQuery.data?.status);
  const components = useQuery({ queryKey: ['components', scanId], queryFn: () => api.components(scanId), enabled: scanReady });
  const findings = useQuery({ queryKey: ['findings', scanId, q], queryFn: () => api.findings(scanId, q), enabled: scanReady });
  if (scanQuery.isLoading) return <LoadingBlock />; if (scanQuery.error) return <ErrorBlock error={scanQuery.error} />; const scan = scanQuery.data!;
  const pending = ['queued', 'processing'].includes(scan.status);
  return <><div className="back-crumb"><Link to="/app/projects">Projects</Link><span>/</span><Link to={`/app/projects/${scan.project_id}`}>Project</Link><span>/</span>Scan details</div><PageTitle eyebrow={`SCAN · ${scan.id.slice(0, 8).toUpperCase()}`} title={scan.source_filename} description={`Started ${date(scan.created_at)} · ${formatBytes(scan.source_bytes)}`} action={<div className="download-actions"><a className="button button-outline button-small" href={`/api/v1/scans/${scan.id}/sbom`}><ArrowDownToLine size={15} /> CycloneDX</a><a className="button button-outline button-small" href={`/api/v1/scans/${scan.id}/report.pdf`}><FileText size={15} /> PDF report</a><a className="button button-quiet button-small" href={`/api/v1/scans/${scan.id}/report.json`} download><ArrowDownToLine size={15} /> JSON</a></div>} />
    <div className={`scan-status-banner ${scan.status === 'partial' ? 'partial' : scan.status === 'failed' ? 'failed' : ''}`}><span className="scan-status-symbol"><ScanIcon status={scan.status} /></span><div><strong>{pending ? scan.stage : scan.status === 'completed' ? 'Scan completed' : scan.status === 'partial' ? 'Partial scan · Review source coverage' : scan.status === 'failed' ? 'Scan failed' : `Scan ${scan.status}`}</strong><p>{pending ? 'The worker updates this status as each stage finishes. This page refreshes automatically.' : scan.error_message || (scan.status === 'completed' ? 'Required package matching and available intelligence sources completed.' : 'Some dependency or intelligence data could not be verified.')}</p></div><StatusBadge status={scan.status} /></div>
    {pending ? <div className="panel progress-panel"><div className="progress-track"><span className="progress-fill" /></div><div className="progress-steps"><span className="done">Upload validated</span><span className={scan.stage.includes('Checking') || scan.stage.includes('Calculating') || scan.stage.includes('Completed') ? 'done' : 'active'}>Dependency analysis</span><span className={scan.stage.includes('Calculating') || scan.stage.includes('Completed') ? 'active' : ''}>Risk and reports</span></div></div> : <>
      <div className="metric-grid scan-metrics"><Metric icon={<FileBox />} label="Components" value={scan.component_count || 0} detail="Extracted dependencies" tone="gold" /><Metric icon={<ShieldAlert />} label="Findings" value={scan.finding_count || 0} detail="Matched advisory instances" tone="red" /><Metric icon={<AlertOctagon />} label="Critical / high" value={(scan.priority_counts?.Critical || 0) + (scan.priority_counts?.High || 0)} detail="DepShield priority" tone="orange" /><MetricText icon={<Clock3 />} label="Scan duration" value={duration(scan.started_at, scan.completed_at)} detail={scan.completed_at ? 'Worker processing time' : 'Not available'} tone="slate" /></div>
      <ScanComparison scanId={scan.id} projectId={scan.project_id} />
      <section className="panel source-panel"><div><span className="eyebrow">INTELLIGENCE COVERAGE</span><h2>Source status</h2><p>Source availability is recorded with this scan. Partial coverage limits conclusions.</p></div><div className="source-chips">{Object.entries(scan.intelligence_status || {}).filter(([key]) => key !== 'last_checked').map(([key, value]) => <span key={key} className={`source-chip ${value === 'available' || value === 'cached' ? 'available' : value === 'disabled' || value === 'not_applicable' ? 'neutral' : 'degraded'}`}><span className="status-bullet" />{key.replace('_', ' ')}<strong>{value.replace('_', ' ')}</strong></span>)}{scan.intelligence_status?.last_checked && <small>Checked {date(scan.intelligence_status.last_checked)}</small>}</div></section>
      {tab === 'findings' && <label className="scan-filter"><Search size={16} /><span className="sr-only">Filter findings</span><input value={q} onChange={e => setQ(e.target.value)} placeholder="Filter package or advisory" /></label>}<div className="tab-row" role="tablist" aria-label="Scan data"><button role="tab" aria-selected={tab === 'findings'} className={tab === 'findings' ? 'active' : ''} onClick={() => setTab('findings')}><ShieldAlert size={16} /> Findings <span>{scan.finding_count || 0}</span></button><button role="tab" aria-selected={tab === 'components'} className={tab === 'components' ? 'active' : ''} onClick={() => setTab('components')}><FileBox size={16} /> Components <span>{scan.component_count || 0}</span></button></div>
      {tab === 'findings' ? <section className="section-block">{findings.isLoading ? <LoadingBlock /> : findings.error ? <ErrorBlock error={findings.error} /> : findings.data?.items.length ? <div className="finding-list">{findings.data.items.map(f => <FindingCard finding={f} key={f.id} />)}</div> : <div className="panel"><EmptyState icon={<ShieldCheck />} title={scan.status === 'partial' ? 'No findings returned from available sources' : 'No vulnerability matches'} text={scan.status === 'partial' ? 'This is not a clean result because some sources or dependencies were unavailable.' : 'The available OSV query returned no matches for resolved package versions. This does not prove the project is free of vulnerabilities.'} /></div>}</section> : <section className="section-block">{components.isLoading ? <LoadingBlock /> : components.error ? <ErrorBlock error={components.error} /> : <ComponentTable components={components.data?.items || []} />}</section>}
    </>}
  </>
}

function ScanComparison({ scanId, projectId }: { scanId: string; projectId: string }) { const scans = useQuery({ queryKey: ['project-scans', projectId], queryFn: () => api.scans(projectId) }); const previous = (scans.data?.items || []).filter(item => item.id !== scanId); const [olderId, setOlderId] = useState(''); const selected = olderId || previous[0]?.id || ''; const compare = useQuery({ queryKey: ['compare', scanId, selected], queryFn: () => api.compareScans(scanId, selected), enabled: Boolean(selected) }); if (previous.length === 0) return null; return <section className="panel compare-panel"><div className="panel-heading"><div><h2>Compare scan history</h2><p>Missing findings are only classified as no longer detected when both scans are complete.</p></div><label className="compare-select"><span className="sr-only">Compare with prior scan</span><select value={selected} onChange={e => setOlderId(e.target.value)}>{previous.map(item => <option key={item.id} value={item.id}>{item.source_filename} · {date(item.created_at)}</option>)}</select></label></div>{compare.isLoading ? <LoadingBlock label="Comparing saved scan snapshots…" /> : compare.error ? <ErrorBlock error={compare.error} /> : compare.data ? <><div className="compare-counts"><span><strong>{compare.data.new_findings.length}</strong> new</span><span><strong>{compare.data.findings_in_both.length}</strong> in both</span><span><strong>{compare.data.no_longer_detected?.length ?? 'N/A'}</strong> no longer detected</span></div>{compare.data.note && <p className="compare-note">{compare.data.note}</p>}{compare.data.new_findings.length > 0 && <div className="compare-list"><strong>Newly detected</strong>{compare.data.new_findings.map(item => <code key={item}>{item}</code>)}</div>}</> : null}</section> }

function FindingCard({ finding }: { finding: Finding }) {
  const [expanded, setExpanded] = useState(false); const explanation = useMutation({ mutationFn: () => api.explain(finding.id) }); const cve = finding.vulnerability.aliases.find(a => a.startsWith('CVE-'));
  return <article className="finding-card"><div className="finding-main"><div className="finding-icon"><SeverityDot severity={finding.official_severity} /></div><div className="finding-content"><div className="finding-title-row"><div><a className="finding-id" href={`https://osv.dev/vulnerability/${encodeURIComponent(finding.vulnerability.osv_id)}`} target="_blank" rel="noreferrer">{cve || finding.vulnerability.osv_id} <ArrowUpRight size={13} /></a><h3>{finding.component.name} <span>{finding.component.version || 'version unresolved'}</span></h3></div><PriorityBadge priority={finding.priority} /></div><p className="finding-summary">{finding.vulnerability.summary || finding.vulnerability.nvd_description || 'No advisory summary was provided by the source.'}</p><div className="finding-meta"><span className="severity-label">Official severity <strong>{finding.official_severity}{finding.cvss !== null ? ` · CVSS ${finding.cvss.toFixed(1)}` : ''}</strong></span><span>DepShield score <strong>{finding.risk_score ?? 'Unknown'}</strong></span><span className={finding.kev_status === 'known' ? 'kev-known' : ''}>CISA KEV <strong>{finding.kev_status.replace('_', ' ')}</strong></span><span>{finding.component.directness} dependency</span>{finding.vulnerability.cwes?.length ? <span>CWE <strong>{finding.vulnerability.cwes.join(', ')}</strong></span> : null}</div></div><button className="icon-button finding-expand" onClick={() => setExpanded(!expanded)} aria-label={expanded ? 'Collapse details' : 'Expand finding details'} aria-expanded={expanded}>{expanded ? <X size={17} /> : <ChevronDown size={17} />}</button></div>
    {expanded && <div className="finding-details"><div className="evidence-grid"><div><span className="detail-label">Risk factors</span><ul className="factor-list">{Object.entries(finding.risk_factors).map(([key, val]) => <li key={key}><span>{key.replace(/_/g, ' ')}</span><strong>{val === null ? 'Unknown' : `+${val}`}</strong></li>)}</ul></div><div><span className="detail-label">Remediation evidence</span>{finding.fixed_versions.length ? <p>OSV lists fixed release(s): <strong>{finding.fixed_versions.join(', ')}</strong>. Check compatibility and confirm the advisory affected range before upgrading.</p> : <p>No fixed version was supplied by the source record. Review the advisory references and maintainer guidance.</p>}<span className="detail-label">Source references</span><div className="reference-links">{finding.vulnerability.references.slice(0, 5).map((ref, i) => { const href = safeExternalUrl(ref.url); return href ? <a key={i} href={href} target="_blank" rel="noopener noreferrer">{ref.url}<ArrowUpRight size={12} /></a> : null })}</div></div></div><div className="explain-area"><button className="button button-outline button-small" onClick={() => explanation.mutate()} disabled={explanation.isPending}><SparkIcon />{explanation.isPending ? 'Preparing explanation…' : 'Explain this finding'}</button>{explanation.error && <p className="form-alert error">{explanation.error.message}</p>}{explanation.data && <div className="explanation-card"><div className="explanation-source"><ShieldCheck size={14} /> {explanation.data.generated_by === 'ollama' ? 'Local Ollama explanation' : 'Deterministic explanation'} · advisory guidance, review before use</div><h4>What it means</h4><p>{explanation.data.explanation}</p><h4>Potential impact</h4><p>{explanation.data.potential_impact}</p><h4>Why this priority</h4><p>{explanation.data.priority_reasoning}</p><h4>Next step</h4><p>{explanation.data.remediation}</p><small>{explanation.data.uncertainty}</small></div>}</div></div>}
  </article>
}
function SparkIcon() { return <ShieldCheck size={15} /> }
function SeverityDot({ severity }: { severity: string }) { return <span className={`severity-dot ${severity.toLowerCase()}`} aria-label={`${severity} severity`} /> }
function PriorityBadge({ priority }: { priority: string }) { return <span className={`priority-badge ${priority.toLowerCase()}`}>{priority === 'Unknown' ? 'Provisional' : `${priority} priority`}</span> }

function ComponentTable({ components }: { components: Component[] }) { const [q, setQ] = useState(''); const rows = components.filter(c => `${c.name} ${c.ecosystem} ${c.manifest}`.toLowerCase().includes(q.toLowerCase())); return <div className="table-panel"><div className="table-tools"><div><h2>Component inventory</h2><p>Versions and dependency relationships shown only when resolved from supplied manifests.</p></div><label className="table-search"><Search size={15} /><input value={q} onChange={e => setQ(e.target.value)} placeholder="Filter components" aria-label="Filter components" /></label></div><div className="table-scroll"><table><thead><tr><th>Component</th><th>Version</th><th>Ecosystem</th><th>Relationship</th><th>Resolution</th><th>Manifest</th></tr></thead><tbody>{rows.map((c, i) => <tr key={c.id || `${c.name}-${i}`}><td><strong>{c.name}</strong>{c.purl && <small className="purl">{c.purl}</small>}</td><td>{c.version || c.version_constraint || 'Unpinned'}</td><td><span className="ecosystem-pill">{c.ecosystem}</span></td><td>{c.directness}</td><td><span className={`resolution ${c.resolution === 'resolved' ? 'resolved' : 'unresolved'}`}>{c.resolution.replace('_', ' ')}</span></td><td>{c.manifest}</td></tr>)}</tbody></table>{!rows.length && <div className="table-empty">No components match the current filter.</div>}</div></div> }

function ExplorerPage() { const [q, setQ] = useState(''); const findings = useQuery({ queryKey: ['explorer', q], queryFn: () => api.searchFindings(q) }); return <><PageTitle eyebrow="VULNERABILITY INTELLIGENCE" title="Vulnerability explorer" description="Search findings across projects you own or can read. Results remain scoped to authorized scans." /><div className="explorer-search"><Search size={18} /><input autoFocus placeholder="Search CVE, advisory ID, package or summary" value={q} onChange={e => setQ(e.target.value)} aria-label="Search vulnerability findings" /><ListFilter size={17} /></div>{findings.isLoading ? <LoadingBlock /> : findings.error ? <ErrorBlock error={findings.error} /> : findings.data?.items.length ? <div className="finding-list">{findings.data.items.map(f => <FindingCard finding={f} key={f.id} />)}</div> : <section className="panel"><EmptyState icon={<Search />} title="No findings to show" text={q ? 'No accessible findings matched this search.' : 'Findings from your completed scans will appear here.'} /></section>}</> }

function SettingsPage() { const user = useWorkspaceUser(); const [name, setName] = useState(user?.display_name || ''); const [notice, setNotice] = useState(''); const [error, setError] = useState(''); const [current, setCurrent] = useState(''); const [next, setNext] = useState(''); const qc = useQueryClient(); const profile = useMutation({ mutationFn: () => api.updateProfile(name), onSuccess: async () => { setNotice('Profile updated.'); await qc.invalidateQueries({ queryKey: ['me'] }) }, onError: e => setError(e.message) }); const password = useMutation({ mutationFn: () => api.changePassword(current, next), onSuccess: () => { setNotice('Password changed. Sign in again.'); location.assign('/login') }, onError: e => setError(e.message) }); return <><PageTitle eyebrow="ACCOUNT" title="Settings" description="Manage your profile, password and session security." /><div className="settings-grid"><section className="panel settings-panel"><div className="panel-heading"><div><h2>Profile</h2><p>Basic account details.</p></div></div><form className="form-stack" onSubmit={e => { e.preventDefault(); setError(''); setNotice(''); profile.mutate() }}><label>Display name<input value={name} maxLength={100} onChange={e => setName(e.target.value)} required /></label><label>Email address<input value={user?.email || ''} disabled /></label><label>Account role<input value={user?.role || ''} disabled /></label><button className="button button-primary" disabled={profile.isPending}>Save profile</button></form></section><section className="panel settings-panel"><div className="panel-heading"><div><h2>Change password</h2><p>Changing the password revokes active sessions.</p></div></div><form className="form-stack" onSubmit={e => { e.preventDefault(); setError(''); password.mutate() }}><label>Current password<input type="password" autoComplete="current-password" value={current} onChange={e => setCurrent(e.target.value)} required /></label><label>New password<input type="password" autoComplete="new-password" minLength={12} maxLength={128} value={next} onChange={e => setNext(e.target.value)} required /></label><button className="button button-primary" disabled={password.isPending}>Update password</button></form></section><section className="panel settings-panel privacy-card"><div className="panel-heading"><div><h2>Privacy controls</h2><p>Local application data and essential cookies.</p></div><LockKeyhole size={18} /></div><p>Uploaded manifest bytes are parsed in memory and discarded. Project details remain until deleted; terminal scan snapshots are pruned according to the configured retention period. Only essential session and CSRF cookies are used.</p><Link to="/privacy" className="text-link">Read privacy details <ArrowRight size={14} /></Link></section><AccountSecurity /></div>{(notice || error) && <p className={`form-alert ${error ? 'error' : 'success'}`} role={error ? 'alert' : 'status'}>{error || notice}</p>}</> }

function AccountSecurity() { const [password, setPassword] = useState(''); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const qc = useQueryClient(); const revoke = useMutation({ mutationFn: api.revokeOtherSessions, onSuccess: result => setMessage(`Revoked ${result.revoked} other session(s).`) }); const remove = useMutation({ mutationFn: () => api.deleteAccount(password), onSuccess: async () => { qc.clear(); location.assign('/') }, onError: e => setError(e.message) }); return <section className="panel settings-panel danger-zone"><div className="panel-heading"><div><h2>Session and account security</h2><p>Revoke sessions or permanently delete this account and its owned project data.</p></div><LockKeyhole size={18} /></div><button className="button button-outline" onClick={() => { setMessage(''); revoke.mutate() }} disabled={revoke.isPending}>Revoke other sessions</button>{message && <p className="form-alert success" role="status">{message}</p>}<form className="form-stack" onSubmit={e => { e.preventDefault(); setError(''); if (confirm('Permanently delete your account and owned projects? This cannot be undone.')) remove.mutate() }}><label>Confirm with your current password<input type="password" autoComplete="current-password" value={password} onChange={e => setPassword(e.target.value)} required /></label>{error && <p className="form-alert error" role="alert">{error}</p>}<button className="button button-danger" disabled={remove.isPending}>{remove.isPending ? 'Deleting…' : 'Delete account and owned data'}</button></form></section> }

function AdminPage() {
  const currentUser = useWorkspaceUser()
  const overview = useQuery({ queryKey: ['admin-overview'], queryFn: api.adminOverview })
  const users = useQuery({ queryKey: ['admin-users'], queryFn: api.adminUsers })
  const jobs = useQuery({ queryKey: ['admin-jobs'], queryFn: api.adminJobs, refetchInterval: 15000 })
  const audit = useQuery({ queryKey: ['admin-audit'], queryFn: api.adminAudit })
  const health = useQuery({ queryKey: ['admin-health'], queryFn: api.adminHealth, refetchInterval: 30000 })
  const qc = useQueryClient()
  const status = useMutation({ mutationFn: ({ id, active }: { id: string; active: boolean }) => api.updateStatus(id, active), onSuccess: () => qc.invalidateQueries({ queryKey: ['admin-users'] }) })
  const role = useMutation({ mutationFn: ({ id, role }: { id: string; role: string }) => api.updateRole(id, role), onSuccess: () => qc.invalidateQueries({ queryKey: ['admin-users'] }) })
  const pageError = overview.error || users.error || jobs.error || audit.error || health.error
  if (pageError) return <ErrorBlock error={pageError} />
  return <>
    <PageTitle eyebrow="ADMINISTRATION" title="Admin console" description="Manage account status, scan jobs and audit activity. Administrator grants require the secure command-line setup." />
    <div className="admin-metrics">{overview.isLoading ? <LoadingBlock /> : <>
      <Metric icon={<Users />} label="Registered users" value={Number(overview.data?.users || 0)} detail={`${overview.data?.active_users || 0} active`} tone="gold" />
      <Metric icon={<FolderKanban />} label="Projects" value={Number(overview.data?.projects || 0)} detail="Stored records" tone="cream" />
      <Metric icon={<Activity />} label="Scans" value={Number(overview.data?.scans || 0)} detail="Historical jobs" tone="slate" />
      <Metric icon={<Clock3 />} label="Jobs queued" value={Number((overview.data?.jobs as Record<string, number>)?.queued || 0)} detail="Worker queue" tone="orange" />
    </>}</div>
    {(status.error || role.error) && <ErrorBlock error={status.error || role.error!} />}
    <section className="section-block"><div className="section-heading-inline"><div><h2>User management</h2><p>Account controls revoke sessions when an account is disabled.</p></div></div>{users.isLoading ? <LoadingBlock /> : <div className="table-panel"><div className="table-scroll"><table><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>{users.data?.items.map(row => <tr key={row.id}><td><strong>{row.display_name}</strong><small className="purl">{row.email}</small></td><td>{row.role === 'administrator' ? <span>Administrator</span> : <select aria-label={`Role for ${row.email}`} value={row.role} onChange={e => role.mutate({ id: row.id, role: e.target.value })}><option value="developer">Developer</option><option value="auditor">Auditor</option></select>}</td><td><StatusBadge status={row.is_active ? 'active' : 'disabled'} /></td><td>{date(row.created_at)}</td><td><button className="button button-outline button-small" onClick={() => status.mutate({ id: row.id, active: !row.is_active })} disabled={status.isPending || row.id === currentUser?.id} title={row.id === currentUser?.id ? 'Current account cannot be disabled here' : undefined}>{row.is_active ? 'Disable' : 'Enable'}</button></td></tr>)}</tbody></table></div></div>}</section>
    <section className="section-block"><div className="section-heading-inline"><div><h2>Scan job queue</h2><p>Latest durable jobs and retry state. Refreshes every 15 seconds.</p></div></div>{jobs.isLoading ? <LoadingBlock /> : !jobs.data?.items.length ? <div className="panel"><EmptyState icon={<Clock3 />} title="No scan jobs" text="Queued scan jobs will appear here." /></div> : <div className="table-panel"><div className="table-scroll"><table><thead><tr><th>Job</th><th>Scan</th><th>Status</th><th>Attempts</th><th>Last error</th><th>Created</th></tr></thead><tbody>{jobs.data.items.map(job => <tr key={job.id}><td><code>{job.id.slice(0, 8)}</code></td><td><Link className="table-link" to={`/app/scans/${job.scan_id}`}>{job.scan_id.slice(0, 8)}</Link></td><td><StatusBadge status={job.status} /></td><td>{job.attempts}/{job.max_attempts}</td><td>{job.last_error || 'N/A'}</td><td>{date(job.created_at)}</td></tr>)}</tbody></table></div></div>}</section>
    <section className="section-block"><div className="section-heading-inline"><div><h2>Recent audit events</h2><p>Security-relevant actions recorded by the application.</p></div></div>{audit.isLoading ? <LoadingBlock /> : !audit.data?.items.length ? <div className="panel"><EmptyState icon={<FileText />} title="No audit events" text="Account and project events will appear here." /></div> : <div className="table-panel"><div className="table-scroll"><table><thead><tr><th>Action</th><th>Target</th><th>Outcome</th><th>Actor</th><th>Details</th><th>Time</th></tr></thead><tbody>{audit.data.items.map(event => <tr key={event.id}><td><code>{event.action}</code></td><td>{event.target_type} {event.target_id ? event.target_id.slice(0, 8) : ''}</td><td>{event.outcome}</td><td>{event.actor_id ? event.actor_id.slice(0, 8) : 'System'}</td><td className="purl">{JSON.stringify(event.metadata || {})}</td><td>{date(event.created_at)}</td></tr>)}</tbody></table></div></div>}</section>
    <section className="panel admin-note"><ShieldCheck size={19} /><p><strong>Service health</strong><br />Database: {health.data?.database || 'Checking'} · CISA KEV: {health.data?.kev_status || 'Checking'} · Ollama: {health.data?.ollama || 'Checking'}. The worker runs separately; see scan job states above.</p></section>
  </>
}
function NotFound() { return <div className="center-page"><div className="not-found"><span>404</span><h1>Page not found</h1><p>The address may be incorrect or the page may have moved.</p><Link className="button button-primary" to="/">Return home</Link></div></div> }

function CookieNotice() { const [show, setShow] = useState(() => localStorage.getItem('depshield-cookie-notice') !== 'dismissed'); if (!show || location.pathname.startsWith('/app')) return null; return <div className="cookie-notice"><ShieldCheck size={17} /><p><strong>Essential cookies only.</strong> Session and CSRF cookies protect sign-in and forms. No optional tracking is enabled. <Link to="/cookies">Details</Link></p><button className="button button-outline button-small" onClick={() => { localStorage.setItem('depshield-cookie-notice', 'dismissed'); setShow(false) }}>Got it</button></div> }

export default function RootApp() { return <><App /><CookieNotice /></> }
